SET NAMES utf8mb4;
START TRANSACTION;
-- Invented booking dates, room assignment, and party size; source values retained.
SET @import_batch_id = (SELECT id FROM import_batches WHERE file_sha256 = 'e829206c8c697074a7d9621ec3fc1d6d4a329bc2309270b49f63630e8fa9eee8');

INSERT INTO bookings
    (guest_id, room_id, check_in, check_out, guests_count, price_total, currency, status, data_origin, import_batch_id, source_record_id)
SELECT c.guest_id, (SELECT r.id FROM rooms r WHERE r.room_type_id=6 AND r.active=TRUE AND r.status='available' ORDER BY r.id LIMIT 1 OFFSET 0), '2027-04-03', '2027-04-04', 1, 2577.00, 'DKK', 'confirmed', 'synthetic_import', @import_batch_id, 'Sheet1:2'
FROM customer_stay_records c
WHERE c.import_batch_id=@import_batch_id AND c.source_record_id='Sheet1:2' AND c.row_status='accepted'
ON DUPLICATE KEY UPDATE guest_id=VALUES(guest_id), room_id=VALUES(room_id), check_in=VALUES(check_in), check_out=VALUES(check_out), guests_count=VALUES(guests_count), price_total=VALUES(price_total), data_origin=VALUES(data_origin);
